const LOGO_B64 = "data:image/png;base64,";
const POSTER_B64 = "data:image/png;base64,";

import { useState, useRef, useEffect, useMemo, useCallback } from "react";
import * as XLSX from "xlsx";

// ─────────────────────────────────────────────────────────────────────────────
// Data model: each row in Excel = one ticket { name, ticketId }
// One win per PERSON (name), not per ticket.
// Winner = a randomly picked ticket → person wins with that ticket shown.
// ─────────────────────────────────────────────────────────────────────────────

const SETTLE_DURATION = 2500;   // settle/converge phase
const RAIN_DROPS = 40;
const ROW_H = 42;
const VISIBLE_ROWS = 14;

